<?php
require dirname(__DIR__).'/config.php';requireAdmin();if(!empty($_SESSION['must_change_password'])){header('Location: password.php');exit;}
$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrf((string)($_POST['csrf_token']??'')))$message='Sesi tidak valid.';elseif(isset($_POST['quiz_state'])){setQuizOpen($_POST['quiz_state']==='open');rotateCsrf();$message=$_POST['quiz_state']==='open'?'Sesi kuis dibuka.':'Sesi kuis ditutup.';}}
$perPage=15;
$pSearch=trim((string)($_GET['participant_q']??''));$pPage=max(1,(int)($_GET['participant_page']??1));$pWhere='';$pParams=[];if($pSearch!==''){$pWhere=' WHERE name LIKE ? OR whatsapp LIKE ? OR tiktok_account LIKE ? OR tiktok_profile_url LIKE ? OR token LIKE ? OR status LIKE ?';$like='%'.$pSearch.'%';$pParams=[$like,$like,$like,$like,$like,$like];}$pCount=db()->prepare('SELECT COUNT(*) FROM participants'.$pWhere);$pCount->execute($pParams);$pTotal=(int)$pCount->fetchColumn();$pPages=max(1,(int)ceil($pTotal/$perPage));$pPage=min($pPage,$pPages);$pOffset=($pPage-1)*$perPage;$pSql="SELECT id,name,whatsapp,tiktok_account,tiktok_profile_url,token,status,correct_count,submitted_at FROM participants{$pWhere} ORDER BY CASE WHEN status='pending' THEN 0 ELSE 1 END ASC, submitted_at ASC, id ASC LIMIT {$perPage} OFFSET {$pOffset}";$pStmt=db()->prepare($pSql);$pStmt->execute($pParams);$rows=$pStmt->fetchAll();
$rSearch=trim((string)($_GET['raffle_q']??''));$rPage=max(1,(int)($_GET['raffle_page']??1));$rWhere='';$rParams=[];if($rSearch!==''){$rWhere=' WHERE r.raffle_number LIKE ? OR p.name LIKE ? OR p.whatsapp LIKE ? OR p.tiktok_account LIKE ? OR p.token LIKE ?';$like='%'.$rSearch.'%';$rParams=[$like,$like,$like,$like,$like];}$rCount=db()->prepare('SELECT COUNT(*) FROM raffle_numbers r JOIN participants p ON p.id=r.participant_id'.$rWhere);$rCount->execute($rParams);$rTotal=(int)$rCount->fetchColumn();$rPages=max(1,(int)ceil($rTotal/$perPage));$rPage=min($rPage,$rPages);$rOffset=($rPage-1)*$perPage;$rSql="SELECT r.raffle_number,p.name,p.whatsapp,p.tiktok_account,p.token,p.correct_count,p.reviewed_at FROM raffle_numbers r JOIN participants p ON p.id=r.participant_id{$rWhere} ORDER BY r.id ASC LIMIT {$perPage} OFFSET {$rOffset}";$rStmt=db()->prepare($rSql);$rStmt->execute($rParams);$raffles=$rStmt->fetchAll();$open=quizIsOpen();
function whatsappChatUrl(string $number):string{return 'https://wa.me/'.preg_replace('/\D+/','',$number);}function pageLinks(int $current,int $pages,string $key):void{if($pages<=1)return;echo '<nav class="pagination">';if($current>1)echo '<a href="'.e(paginationUrl([$key=>$current-1])).'">‹ Sebelumnya</a>';echo '<span>Halaman '.$current.' dari '.$pages.'</span>';if($current<$pages)echo '<a href="'.e(paginationUrl([$key=>$current+1])).'">Berikutnya ›</a>';echo '</nav>';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Kuis Affan Elektronik</title><link rel="icon" type="image/png" href="../assets/favicon.png"><link rel="shortcut icon" href="../assets/favicon.ico"><link rel="stylesheet" href="../assets/style.css"></head><body><div class="container wide"><div class="card"><div class="admin-brand"><img src="../assets/affan-logo.png" alt="Affan Elektronik"><span>Panel Kuis Affan Elektronik</span></div><div class="topbar"><h1>Data Peserta</h1><div><a class="small-button" href="export.php">Export Excel Nomor Undian</a> <a class="small-button" href="password.php">Ganti Password</a> <a href="logout.php">Logout</a></div></div><?php if($message):?><div class="success-alert"><?=e($message)?></div><?php endif;?><div class="session-box"><div><strong>Status kuis:</strong> <span class="status-badge <?=$open?'open':'closed'?>"><?=$open?'DIBUKA':'DITUTUP'?></span></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="quiz_state" value="<?=$open?'closed':'open'?>"><button type="submit" class="<?=$open?'danger-button':''?>"><?=$open?'Tutup Sesi Kuis':'Buka Sesi Kuis'?></button></form></div>
<div class="topbar section-heading"><div><h2>Daftar Peserta</h2><p class="muted">Belum direview paling atas, lalu pengiriman paling awal.</p></div><form method="get" class="table-search server-search"><label for="participant_q">Cari peserta</label><div class="search-row"><input type="search" id="participant_q" name="participant_q" value="<?=e($pSearch)?>" placeholder="Nama, WA, token, status..."><input type="hidden" name="raffle_q" value="<?=e($rSearch)?>"><button type="submit" class="small-button">Cari</button><?php if($pSearch!==''):?><a class="small-button secondary-button" href="<?=e(paginationUrl(['participant_q'=>null,'participant_page'=>null]))?>">Reset</a><?php endif;?></div></form></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>WhatsApp</th><th>Akun / Username TikTok</th><th>Link Profile</th><th>Token</th><th>Status</th><th>Benar</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><a href="<?=e(whatsappChatUrl((string)$r['whatsapp']))?>" target="_blank" rel="noopener noreferrer"><?=e($r['whatsapp'])?></a></td><td><?=e((string)$r['tiktok_account'])?></td><td><a href="<?=e((string)$r['tiktok_profile_url'])?>" target="_blank" rel="noopener noreferrer">Buka Profile</a></td><td><?=e($r['token'])?></td><td><?=e($r['status'])?></td><td><?=(int)$r['correct_count']?></td><td><?=e($r['submitted_at'])?></td><td><a class="small-button" href="review.php?id=<?=(int)$r['id']?>">Koreksi</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9">Data peserta tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><div class="table-footer"><span>Menampilkan <?=count($rows)?> dari <?=$pTotal?> peserta</span><?php pageLinks($pPage,$pPages,'participant_page');?></div>
<div class="topbar section-heading"><div><h2>Daftar Nomor Undian</h2><p class="muted">Nomor urut unik beserta pemiliknya.</p></div><div class="table-actions"><form method="get" class="table-search server-search"><label for="raffle_q">Cari nomor undian</label><div class="search-row"><input type="search" id="raffle_q" name="raffle_q" value="<?=e($rSearch)?>" placeholder="Nomor, nama, WA, token..."><input type="hidden" name="participant_q" value="<?=e($pSearch)?>"><button type="submit" class="small-button">Cari</button><?php if($rSearch!==''):?><a class="small-button secondary-button" href="<?=e(paginationUrl(['raffle_q'=>null,'raffle_page'=>null]))?>">Reset</a><?php endif;?></div></form><a class="small-button" href="export.php">Export Excel</a></div></div><div class="table-wrap"><table><thead><tr><th>No.</th><th>Nomor Undian</th><th>Nama Pemilik</th><th>Nomor WhatsApp</th><th>Akun / Username TikTok</th><th>Token</th><th>Total Benar</th><th>Tanggal Koreksi</th></tr></thead><tbody><?php foreach($raffles as $i=>$r):?><tr><td><?=$rOffset+$i+1?></td><td><strong><?=e($r['raffle_number'])?></strong></td><td><?=e($r['name'])?></td><td><a href="<?=e(whatsappChatUrl((string)$r['whatsapp']))?>" target="_blank" rel="noopener noreferrer"><?=e($r['whatsapp'])?></a></td><td><?=e((string)$r['tiktok_account'])?></td><td><?=e($r['token'])?></td><td><?=(int)$r['correct_count']?></td><td><?=e((string)$r['reviewed_at'])?></td></tr><?php endforeach;?><?php if(!$raffles):?><tr><td colspan="8">Nomor undian tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><div class="table-footer"><span>Menampilkan <?=count($raffles)?> dari <?=$rTotal?> nomor undian</span><?php pageLinks($rPage,$rPages,'raffle_page');?></div></div></div></body></html>
